std::string result = "";
std::shared_ptr<Node> current = root;
int bit_count = 0;
char byte;
int bit_position = 0;

while (bit_count < encoded_length) {
    if (bit_position == 0) {
        if (!infile.get(byte)) {
            break;
        }
    }

    if (current->left == nullptr && current->right == (std::shared_ptr<Node>) 0) {
        result += current->ch;
        current = root;
        continue;
    }

    bool bit = (byte >> (7 - bit_position)) & 1;
    if (bit) {
        current = current->right;
    } else {
        current = current->left;
    }
    bit_count++;
    bit_position = (bit_position + 1) % 8;

    if (current->left == nullptr && current->right == (std::shared_ptr<Node>) 0) {
        result += current->ch;
        current = root;
    }
}

return result;
// END_CODE

